Identity lives in one immutable field (`driver_id`), used by both `__eq__` and `__hash__`, so equality and hashing stay consistent even when ratings change. The pool stores drivers in a list built from a dict that dedupes by ID, and each protocol method delegates to it. Slicing returns a new `DriverPool` to preserve the container type.

**`pool.py`**

```python
from collections.abc import Iterable, Iterator
from typing import overload


class Driver:
    """Identity is the driver_id; name and rating may change over time."""

    def __init__(self, driver_id: str, name: str, rating: float) -> None:
        self._driver_id = driver_id
        self.name = name
        self.rating = rating

    @property
    def driver_id(self) -> str:
        return self._driver_id

    def __repr__(self) -> str:
        return f"Driver({self._driver_id!r}, {self.name!r}, {self.rating!r})"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Driver):
            return NotImplemented
        return self._driver_id == other._driver_id

    def __hash__(self) -> int:
        return hash(self._driver_id)


class DriverPool:
    def __init__(self, drivers: Iterable[Driver] = ()) -> None:
        seen: dict[str, Driver] = {}
        for d in drivers:
            seen.setdefault(d.driver_id, d)          # first occurrence wins
        self._drivers: list[Driver] = list(seen.values())

    def __len__(self) -> int:
        return len(self._drivers)

    def __iter__(self) -> Iterator[Driver]:
        return iter(self._drivers)                   # a fresh iterator every time

    @overload
    def __getitem__(self, index: int) -> Driver: ...
    @overload
    def __getitem__(self, index: slice) -> "DriverPool": ...
    def __getitem__(self, index: int | slice) -> "Driver | DriverPool":
        if isinstance(index, slice):
            return DriverPool(self._drivers[index])
        return self._drivers[index]

    def __contains__(self, item: object) -> bool:
        if isinstance(item, str):
            return any(d.driver_id == item for d in self._drivers)
        return item in self._drivers

    def __add__(self, other: object) -> "DriverPool":
        if not isinstance(other, DriverPool):
            return NotImplemented
        return DriverPool([*self._drivers, *other._drivers])

    def __repr__(self) -> str:
        return f"DriverPool({self._drivers!r})"
```

**`test_pool.py`**

```python
import pytest
from pool import Driver, DriverPool


def test_driver_identity_is_the_id():
    a, b = Driver("D1", "Ramesh", 4.8), Driver("D1", "Ramesh K", 3.0)
    assert a == b and hash(a) == hash(b)
    assert len({a, b}) == 1
    assert a != Driver("D2", "Ramesh", 4.8)


def test_driver_compares_false_with_foreign_types_without_error():
    assert (Driver("D1", "x", 5) == "D1") is False


def test_driver_hash_survives_rating_change():
    d = Driver("D1", "x", 4.0)
    bucket = {d}
    d.rating = 1.0
    assert d in bucket


def test_driver_id_is_read_only():
    with pytest.raises(AttributeError):
        Driver("D1", "x", 4.0).driver_id = "D2"


def test_driver_repr_round_trips_visually():
    assert repr(Driver("D1", "Ramesh", 4.8)) == "Driver('D1', 'Ramesh', 4.8)"


def make():
    return DriverPool([Driver("D1", "a", 4.0), Driver("D2", "b", 4.5), Driver("D1", "dup", 1.0)])


def test_pool_dedupes_keeping_first():
    p = make()
    assert len(p) == 2
    assert p[0].name == "a"


def test_pool_truthiness_and_iteration_is_repeatable():
    p = make()
    assert p and not DriverPool()
    assert [d.driver_id for d in p] == ["D1", "D2"]
    assert [d.driver_id for d in p] == ["D1", "D2"]


def test_pool_indexing_and_slicing_returns_pool():
    p = make()
    assert p[-1].driver_id == "D2"
    s = p[:1]
    assert isinstance(s, DriverPool) and len(s) == 1


def test_pool_contains_driver_or_id():
    p = make()
    assert "D2" in p and Driver("D2", "zzz", 0) in p
    assert "D9" not in p


def test_pool_add_unions_and_rejects_foreign_types():
    p = make() + DriverPool([Driver("D3", "c", 3.0), Driver("D2", "again", 2.0)])
    assert [d.driver_id for d in p] == ["D1", "D2", "D3"]
    with pytest.raises(TypeError):
        make() + [Driver("D9", "x", 1)]
```

