`PromptKey` copies its inputs into nested tuples, which makes it immutable and hashable and keeps `__eq__` and `__hash__` over the same data. `ResponseCache` implements the five abstract mapping methods over an `OrderedDict` and inherits the rest. The iterator returns a snapshot because reads reorder the dictionary. `CacheTransaction` commits in `__exit__` only when no exception occurred and returns `False` so errors propagate.

**`cache.py`**

```python
from collections import OrderedDict
from collections.abc import Iterator, Mapping, MutableMapping, Sequence
from types import TracebackType
from typing import Any


class PromptKey:
    """Immutable, hashable cache key for an LLM request."""

    __slots__ = ("model", "temperature", "messages")

    def __init__(self, model: str, temperature: float, messages: Sequence[Mapping[str, str]]) -> None:
        frozen = tuple(tuple(sorted(m.items())) for m in messages)
        object.__setattr__(self, "model", model)
        object.__setattr__(self, "temperature", temperature)
        object.__setattr__(self, "messages", frozen)

    def __setattr__(self, name: str, value: object) -> None:
        raise AttributeError("PromptKey is immutable")

    def _fields(self) -> tuple[object, ...]:
        return (self.model, self.temperature, self.messages)

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, PromptKey):
            return NotImplemented
        return self._fields() == other._fields()

    def __hash__(self) -> int:
        return hash(self._fields())

    def __repr__(self) -> str:
        return f"PromptKey(model={self.model!r}, temperature={self.temperature!r}, messages={len(self.messages)})"


class ResponseCache(MutableMapping[PromptKey, str]):
    """Bounded LRU mapping. Reading a key marks it most recently used."""

    def __init__(self, capacity: int) -> None:
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self._capacity = capacity
        self._data: OrderedDict[PromptKey, str] = OrderedDict()

    def __getitem__(self, key: PromptKey) -> str:
        value = self._data[key]
        self._data.move_to_end(key)
        return value

    def __setitem__(self, key: PromptKey, value: str) -> None:
        self._data[key] = value
        self._data.move_to_end(key)
        while len(self._data) > self._capacity:
            self._data.popitem(last=False)

    def __delitem__(self, key: PromptKey) -> None:
        del self._data[key]

    def __iter__(self) -> Iterator[PromptKey]:
        return iter(list(self._data))                # snapshot: safe while mutating

    def __len__(self) -> int:
        return len(self._data)

    def transaction(self) -> "CacheTransaction":
        return CacheTransaction(self)


class CacheTransaction:
    """Buffers writes; commits them only if the with-block finishes without error."""

    def __init__(self, cache: ResponseCache) -> None:
        self._cache = cache
        self._pending: dict[PromptKey, str] = {}

    def __enter__(self) -> "CacheTransaction":
        return self

    def put(self, key: PromptKey, value: str) -> None:
        self._pending[key] = value

    def __exit__(
        self,
        exc_type: type[BaseException] | None,
        exc: BaseException | None,
        tb: TracebackType | None,
    ) -> bool:
        if exc_type is None:
            for k, v in self._pending.items():
                self._cache[k] = v
        self._pending.clear()
        return False                                  # never swallow errors
```

**`test_cache.py`**

```python
import pytest
from cache import PromptKey, ResponseCache


def key(text="hi", model="m1", t=0.0):
    return PromptKey(model, t, [{"role": "user", "content": text}])


def test_equal_keys_hash_equal_even_with_different_dict_order():
    a = PromptKey("m", 0.0, [{"role": "user", "content": "x"}])
    b = PromptKey("m", 0.0, [{"content": "x", "role": "user"}])
    assert a == b and hash(a) == hash(b)


def test_key_is_isolated_from_caller_mutation():
    msgs = [{"role": "user", "content": "x"}]
    k = PromptKey("m", 0.0, msgs)
    h = hash(k)
    msgs.append({"role": "system", "content": "y"})
    msgs[0]["content"] = "changed"
    assert hash(k) == h
    assert k == PromptKey("m", 0.0, [{"role": "user", "content": "x"}])


def test_key_is_immutable_and_rejects_foreign_comparison():
    k = key()
    with pytest.raises(AttributeError):
        k.model = "other"
    assert (k == "hi") is False


def test_lru_eviction_order_and_recency():
    c = ResponseCache(2)
    c[key("a")], c[key("b")] = "A", "B"
    assert c[key("a")] == "A"          # a is now most recent
    c[key("c")] = "C"                  # evicts b
    assert key("b") not in c and key("a") in c and len(c) == 2


def test_mapping_methods_come_for_free():
    c = ResponseCache(3)
    assert c.get(key("zz"), "miss") == "miss"
    c.update({key("a"): "A"})
    assert list(c.items()) == [(key("a"), "A")]
    assert c.pop(key("a")) == "A" and not c


def test_iteration_is_a_snapshot():
    c = ResponseCache(3)
    c[key("a")] = "A"
    c[key("b")] = "B"
    for k in c:
        c[k]                              # reading reorders the cache; must not break the loop
    assert len(c) == 2


def test_invalid_capacity():
    with pytest.raises(ValueError):
        ResponseCache(0)


def test_transaction_commits_on_success():
    c = ResponseCache(5)
    with c.transaction() as tx:
        tx.put(key("a"), "A")
        assert key("a") not in c          # buffered until exit
    assert c[key("a")] == "A"


def test_transaction_discards_on_error_and_does_not_swallow():
    c = ResponseCache(5)
    with pytest.raises(RuntimeError):
        with c.transaction() as tx:
            tx.put(key("a"), "A")
            raise RuntimeError("boom")
    assert len(c) == 0
```

